#include <iostream>
#include <vector>

void duplicate_evens(std::vector<int>& v) {
    // Repair the original loop. Duplicate only the original even elements.
    for (const auto& x : v) {
        if (x % 2 == 0) v.push_back(x);
    }
}

int main() {
    std::vector<int> v = {1, 2, 3, 4};
    duplicate_evens(v);
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';
}

