#define main exercise_main
#include "main.cpp"
#undef main
#include <cassert>

int main() {
    auto check = [](std::vector<int> input, std::vector<int> expected) {
        input.shrink_to_fit();
        duplicate_evens(input);
        assert(input == expected);
    };
    check({}, {});
    check({1, 3, 5}, {1, 3, 5});
    check({1, 2, 3, 4}, {1, 2, 3, 4, 2, 4});
    check({0, -2, 2}, {0, -2, 2, 0, -2, 2});
    std::vector<int> reserved = {2, 4};
    reserved.reserve(100);
    duplicate_evens(reserved);
    assert((reserved == std::vector<int>{2, 4, 2, 4}));
    std::cout << "All 5 example cases passed\n";
}

